extra_sources={'01-010':['fe-last-slavic-household','fe-last-procopius'],'04-008':['fe-last-ugra'],'05-005':['fe-last-oprichnina-museum','fe-last-oprichnina-encyclopedia'],'05-010':['fe-last-godunov']}
for id,sections in new.items():
 p=Path('src/content/lessons')/f'{id}.json';d=json.loads(p.read_text());old=json.loads(json.dumps(d));titles={s['title'] for s in d['sections']}
 for title,paragraphs in sections:
  if title not in titles:d['sections'].append({'title':title,'paragraphs':paragraphs})
 for source in extra_sources[id]:
  if source not in d['sources']:d['sources'].append(source)
 assert d['sections'][:len(old['sections'])]==old['sections']
 for key in old:
  if key not in {'sections','sources'}:assert old[key]==d[key],(id,key)
 words=len(' '.join(p for s in d['sections'] for p in s['paragraphs']).split());assert 700<=words<=900,(id,words)
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print(id,words)
